func TestListExchangesCopiesAreIndependent(t *testing.T) {
	f := setupExchange(t)
	x1, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID,
		[]ID{f.diag}, "req-iso-list-1")
	if err != nil {
		t.Fatal(err)
	}
