// ---- 待回执交换：在手中结果里补造假回执，重新查询仍没有回执 ----

func TestFabricatedReceiptOnPendingExchangeDoesNotPersist(t *testing.T) {
	f := setupExchange(t)
	x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID,
