337	func TestFetchPackageRechecksBinding(t *testing.T) {
338		f := setupExchange(t)
339		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag, f.ord}, "req-fetch")
