431	func TestFetchPackageJudgesBindingAtCheckTimeNotRequestTime(t *testing.T) {
432		f := setupExchange(t)
433		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag, f.ord}, "req-wait")
434		if err != nil {
435			t.Fatal(err)
436		}
437	
438		// 另一条同患者、同接收方、覆盖相同记录且在核对时刻仍有效的授权：
439		// 绑定授权到期后也不能用它替代。
440		otherAuth, err := f.s.Grant(doc, f.pid, rcv.ID,
441			[]Scope{{EncounterID: f.e1, Category: Diagnosis}, {EncounterID: f.e1, Category: Order}},
442			f.start, f.end.Add(24*time.Hour))
443		if err != nil {
444			t.Fatal(err)
445		}
446		_ = otherAuth
447	
448		// 请求在截止前一分钟发出，等待期间恰好到达截止时刻：核对时绑定授权
449		// 已失效，必须拒绝；交付为空，不携带包内容、摘要、记录标识或交换状态。
450		f.clk.t = f.end.Add(-time.Minute)
451		del, err := fetchWhileStoreBusy(f.s, f.clk, f.end, rcv, x.ID)
452		if !errors.Is(err, ErrAccessDenied) {
453			t.Fatalf("binding expired during wait: err = %v, want ErrAccessDenied", err)
454		}
455		if !emptyDelivery(del) {
456			t.Fatalf("denied delivery must carry no exchange info: %+v", del)
457		}
458	
459		// 核对发生在截止前一刻（仍有等待）：其他条件满足，取包成功，
460		// 返回创建时固化的包与摘要、当前状态。
461		f.clk.t = f.end.Add(-2 * time.Minute)
462		del, err = fetchWhileStoreBusy(f.s, f.clk, f.end.Add(-time.Nanosecond), rcv, x.ID)
463		if err != nil {
464			t.Fatalf("check just before expiry must succeed: %v", err)
465		}
466		if del.ExchangeID != x.ID || del.Digest != x.Digest || del.Status != ExchangePending {
467			t.Fatalf("bad delivery: %+v", del)
468		}
469		if len(del.Package.Records) != 2 {
470			t.Fatalf("delivery records = %d, want 2", len(del.Package.Records))
471		}
472	
473		// 没有等待的正常取包同样遵守半开边界：恰好截止时刻失效，
474		// 截止前一纳秒仍可取，边界语义与 Read 完全一致。
475		f.clk.t = f.end
476		if del, err := f.s.FetchPackage(rcv, x.ID); !errors.Is(err, ErrAccessDenied) {
477			t.Fatalf("fetch exactly at expiry: err = %v, want ErrAccessDenied, delivery = %+v", err, del)
478		}
479		f.clk.t = f.end.Add(-time.Nanosecond)
480		if _, err := f.s.FetchPackage(rcv, x.ID); err != nil {
481			t.Fatalf("fetch just before expiry: %v", err)
482		}
483	}
484	
485	// fetchWhileStoreBusyLocked 在已持有存储锁的前提下发起取包，等待 goroutine
486	// 阻塞在锁上后执行 mutate（直接改动内存快照）再放行：用于模拟“请求先发出、
487	// 其他操作先完成、本次核对随后才开始”的排队场景。
488	func fetchWhileStoreBusyLocked(s *Store, mutate func(snap *snapshot, now time.Time), actor Actor, exchangeID ID) (PackageDelivery, error) {
489		done := make(chan struct {
490			del PackageDelivery
491			err error
492		}, 1)
493		go func() {
494			del, err := s.FetchPackage(actor, exchangeID)
495			done <- struct {
496				del PackageDelivery
497				err error
498			}{del, err}
499		}()
500		// 给取包 goroutine 留出进入 FetchPackage 并阻塞在锁上的时间，确保请求
501		// 是在下面的状态改动之前发出的。
502		time.Sleep(50 * time.Millisecond)
503		mutate(s.data, s.now())
504		s.mu.Unlock()
505		o := <-done
506		return o.del, o.err
507	}
