// ---- 并发重试只产生一份交换 ----

func TestConcurrentCreateExchangeProducesOne(t *testing.T) {
	f := setupExchange(t)
	const n = 16
	var wg sync.WaitGroup
	errs := make([]error, n)
	ids := make([]ID, n)
	wg.Add(n)
	for i := 0; i < n; i++ {
		i := i
		go func() {
			defer wg.Done()
			x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID,
				[]ID{f.diag, f.ord}, "req-concurrent")
			errs[i] = err
			ids[i] = x.ID
		}()
	}
	wg.Wait()
	for i, err := range errs {
		if err != nil {
			t.Fatalf("goroutine %d: %v", i, err)
		}
		if ids[i] != ids[0] {
			t.Fatalf("goroutine %d got %q, want %q", i, ids[i], ids[0])
		}
	}
	xs, _ := f.s.ListExchanges(doc, f.pid)
	if len(xs) != 1 {
		t.Fatalf("exchanges = %d, want 1", len(xs))
	}
	var createEvents int
	for _, ev := range mustAudit(t, f.s, f.pid) {
		if ev.Action == ActionExchanged {
			createEvents++
		}
	}
	if createEvents != 1 {
		t.Fatalf("exchange_created events = %d, want 1", createEvents)
	}
}

// ---- 重开恢复：原包、重试结果、回执、审计全部保留 ----

func TestExchangePersistenceAcrossReopen(t *testing.T) {
	dir := t.TempDir()
	clk := &fakeClock{t: time.Date(2026, 4, 1, 8, 0, 0, 0, time.UTC)}
	open := func() *Store {
		s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
		if err != nil {
			t.Fatalf("open: %v", err)
		}
		return s
	}

	s := open()
	p, _ := s.RegisterPatient(doc, "持久化交换患者")
	e, _ := s.AddEncounter(doc, p.ID, time.Time{})
	rec, _ := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "包内v1")
	v1, _ := s.ActivateRecord(doc, rec.ID)
	a, _ := s.Grant(doc, p.ID, rcv.ID, []Scope{{EncounterID: e.ID, Category: Diagnosis}},
		clk.t.Add(-time.Hour), clk.t.Add(48*time.Hour))

	x, err := s.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rec.ID}, "req-persist")
	if err != nil {
		t.Fatal(err)
	}
	// 打包后更正：包固定在 v1。
	if _, err := s.CorrectRecord(doc, rec.ID, 1, "当前v2", "事后更正"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, "重开前拒绝"); err != nil {
		t.Fatal(err)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}

	s2 := open()
	t.Cleanup(func() { _ = s2.Close() })

	// 原包内容固定为 v1，回执保留。
	got, err := s2.GetExchange(doc, p.ID, x.ID)
	if err != nil {
		t.Fatalf("get after reopen: %v", err)
	}
	if got.Status != ExchangeRejected || got.Receipt == nil || got.Receipt.Reason != "重开前拒绝" {
		t.Fatalf("receipt lost: %+v", got)
	}
	if len(got.Package.Records) != 1 || got.Package.Records[0].VersionID != v1.ID ||
		got.Package.Records[0].Content != "包内v1" {
		t.Fatalf("frozen package lost: %+v", got.Package.Records)
	}

	// 同请求号重试仍返回原交换，不新增审计。
	auditBefore := len(mustAudit(t, s2, p.ID))
	retry, err := s2.CreateExchange(doc, p.ID, rcv.ID, a.ID, []ID{rec.ID}, "req-persist")
	if err != nil {
		t.Fatalf("retry after reopen: %v", err)
	}
	if retry.ID != x.ID || retry.Status != ExchangeRejected {
		t.Fatalf("retry after reopen = %+v", retry)
	}
	if retry.Package.Records[0].Content != "包内v1" {
		t.Fatalf("retry refetched current content: %+v", retry.Package.Records)
	}
	if n := len(mustAudit(t, s2, p.ID)); n != auditBefore {
		t.Fatalf("retry after reopen added audit: %d", n)
	}

	// 审计两类事件都在。
	var creates, receipts int
	for _, ev := range mustAudit(t, s2, p.ID) {
		switch ev.Action {
		case ActionExchanged:
			creates++
		case ActionReceipted:
			receipts++
		}
	}
	if creates != 1 || receipts != 1 {
		t.Fatalf("audit after reopen: creates=%d receipts=%d", creates, receipts)
	}

	// 取包路径在重开后同样按当前时间与绑定授权判断（窗口内可取）。
	del, err := s2.FetchPackage(rcv, x.ID)
	if err != nil {
		t.Fatalf("fetch after reopen: %v", err)
	}
	if del.Digest != x.Digest || del.Status != ExchangeRejected {
		t.Fatalf("delivery after reopen wrong: %+v", del)
	}
}

// 关闭后调用返回 ErrClosed。
func TestExchangeOperationsAfterClose(t *testing.T) {
	f := setupExchange(t)
	x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "req-closed")
	if err != nil {
		t.Fatal(err)
	}
	if err := f.s.Close(); err != nil {
		t.Fatal(err)
	}
	if _, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "req-closed-2"); !errors.Is(err, ErrClosed) {
		t.Fatalf("create after close err = %v", err)
	}
	if _, err := f.s.FetchPackage(rcv, x.ID); !errors.Is(err, ErrClosed) {
		t.Fatalf("fetch after close err = %v", err)
	}
	if _, err := f.s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptAccepted, ""); !errors.Is(err, ErrClosed) {
		t.Fatalf("receipt after close err = %v", err)
	}
	if _, err := f.s.GetExchange(doc, f.pid, x.ID); !errors.Is(err, ErrClosed) {
		t.Fatalf("get after close err = %v", err)
	}
}

package clinical

import (
	"errors"
	"time"
)

// 记录类别：诊断与医嘱。
const (
	Diagnosis = "diagnosis"
	Order     = "order"
)

// 审计动作。
const (
	ActionActivated   = "activated"
	ActionCorrected   = "corrected"
	ActionGranted     = "authorization_granted"
	ActionRevoked     = "authorization_revoked"
	ActionDeactivated = "patient_deactivated"
	ActionExchanged   = "exchange_created"
	ActionReceipted   = "receipt_registered"
)

// 合成数据标记。本包只处理合成患者资料，登记时统一写入。
const SyntheticSource = "synthetic"

// 调用方身份。Internal 为内部使用者，Receiver 为接收方。
//
// 内部使用者可查看全部草稿与完整历史、建立与撤回授权、维护档案；
// 接收方只能凭有效授权读取当前生效版本。
type Actor struct {
	ID   string
	Kind string // "internal" 或 "receiver"
}

// InternalActor 构造一个内部使用者身份。
func InternalActor(id string) Actor { return Actor{ID: id, Kind: "internal"} }

// ReceiverActor 构造一个接收方身份。
func ReceiverActor(id string) Actor { return Actor{ID: id, Kind: "receiver"} }

// IsInternal 报告该身份是否为内部使用者。
func (a Actor) IsInternal() bool { return a.Kind == "internal" }

func (a Actor) valid() bool {
	if a.ID == "" {
		return false
	}
	return a.Kind == "internal" || a.Kind == "receiver"
}

// ID 是患者、就诊、记录、版本、授权与审计事件的稳定标识。
// ID 在各自类型的集合内唯一，由登记操作生成并原样返回，
// 关闭后从同一位置重新打开仍然有效。
type ID = string

// Patient 是一名合成患者的档案。
type Patient struct {
	ID          ID
	Name        string
	Source      string // 始终为 SyntheticSource
	Deactivated bool
	CreatedAt   time.Time
}

// Encounter 是患者的一次就诊。
type Encounter struct {
	ID         ID
	PatientID  ID
	OccurredAt time.Time
	CreatedAt  time.Time
}

// Version 是一条记录在某一时刻被固化的完整内容。
// 生效产生第 1 版；每次更正产生新版本并通过 PrevID 链接到上一版本。
type Version struct {
	ID        ID
	RecordID  ID
	Number    int
	Content   string
	Category  string
	CreatedAt time.Time // 生效或更正发生的时间
	PrevID    ID        // 上一版本；第 1 版为空
	Reason    string    // 更正原因；第 1 版为空
}

// Record 是一条诊断或医嘱。它在草稿与版本之间推进：
// 草稿可反复修改或删除；生效后产生不可变的当前版本，
// 此后只能通过更正产生新版本，不能被直接覆盖或删除。
type Record struct {
	ID          ID
	PatientID   ID
	EncounterID ID
	Category    string

	DraftContent string
	HasDraft     bool

	CurrentVersionID ID
	Versions         []ID // 按版本号顺序，旧到新
}

// Authorization 是内部使用者为一名接收方建立的、针对某患者的读取授权。
// 范围由两类条目组成，二者可并存、均可覆盖多条就诊与类别：
//
//   - Scopes：整类范围，覆盖某次就诊下某个类别（诊断/医嘱）的全部已生效
//     记录，含授权建立之后才生效的记录；读取时始终取记录的当前生效版本。
//   - Selections：限定范围，仅覆盖明确选出的具体记录。被选记录被更正后
//     授权覆盖它的当前版本；但同一就诊同一类别的其他记录、以及后来新增
//     并生效的记录都不会自动进入限定范围。
//
// 授权仅在 [StartsAt, ExpiresAt) 内有效。
type Authorization struct {
	ID         ID
	PatientID  ID
	ReceiverID string
	Scopes     []Scope
	// Selections 为限定范围中明确选出的记录。为空表示该授权只有整类范围；
	// 旧数据与 Grant 建立的授权该字段始终为空。
	Selections []RecordSelection
	StartsAt   time.Time
	ExpiresAt  time.Time
	RevokedAt  *time.Time // 撤回时间；nil 表示未撤回
	CreatedAt  time.Time
}

// ActiveAt 报告授权在时刻 t 是否有效：已开始、未到期、未撤回。
// 开始时刻即生效；到截止时刻立即失效（半开区间 [StartsAt, ExpiresAt)）。
func (a *Authorization) ActiveAt(t time.Time) bool {
	if a.RevokedAt != nil {
		return false
	}
	if t.Before(a.StartsAt) {
		return false
	}
	if !t.Before(a.ExpiresAt) {
		return false
	}
	return true
}

// Scope 是授权范围中的一项：某次就诊下的某个记录类别。
type Scope struct {
	EncounterID ID
	Category    string
}

// RecordSelection 是授权限定范围中的一项：明确选出某条已生效记录，
// 并声明它所属的就诊与类别。建立授权时记录必须存在、已生效、属于该
// 患者，且其实际就诊与类别必须与声明一致；同一记录在一条授权内重复
// 选择只算一次。
type RecordSelection struct {
	EncounterID ID
	Category    string
	RecordID    ID
}

// AuditEvent 是一条仅供内部使用者按患者查看的审计事件。
type AuditEvent struct {
	ID         ID
	PatientID  ID
	ActorID    string
	Action     string
	ObjectType string
	ObjectID   ID
	OccurredAt time.Time
}

// ReadResult 是接收方一次受限读取得到的内容。
type ReadResult struct {
	EncounterID ID
	Category    string
	// Records 为该就诊该类别下、当前生效且被有效授权覆盖的记录，
	// 每项只含当前生效版本的完整内容，不含草稿、旧版本或更正原因。
	Records []EffectiveRecord
}

// EffectiveRecord 是对外暴露的一条当前生效记录。
type EffectiveRecord struct {
	RecordID    ID
	VersionID   ID
	Version     int
	Content     string
	EffectiveAt time.Time
}

// 交换状态：创建后待回执，接收方登记回执后转为已接受或已拒绝。
const (
	ExchangePending  = "pending_receipt"
	ExchangeAccepted = "accepted"
	ExchangeRejected = "rejected"
)

// 回执结果：接受或拒绝打包内容。
const (
	ReceiptAccepted = "accepted"
	ReceiptRejected = "rejected"
)

// PackagedRecord 是包内固化的一条记录版本。包在创建时取各记录的当前生效
// 版本快照：此后记录被更正或新增版本都不会改写包内容。
//
// 只含核对所需的标识、版本号、生效时间与完整内容，不含患者姓名、草稿、
// 历史版本或更正原因（Version.Reason）。
type PackagedRecord struct {
	EncounterID ID
	Category    string
	RecordID    ID
	VersionID   ID
	Version     int
	EffectiveAt time.Time
	Content     string
}

// Package 是一份已固化的交换内容：只含患者与接收方标识及各记录的版本快照。
type Package struct {
	PatientID  ID
	ReceiverID string
	Records    []PackagedRecord
}

// Receipt 是接收方对一份包的回执。接受时 Reason 为空（传入原因一律忽略）；
// 拒绝时 Reason 必填、非空白且必须是合法 UTF-8，原样保存。
type Receipt struct {
	Outcome      string
	Reason       string
	RegisteredAt time.Time
}

// Exchange 是把已授权记录打包给指定接收方的一次交换。
//
// 创建即把当时的当前版本固化进 Package 并计算摘要；状态初始为待回执。
// 请求号（RequestID）按发起的内部使用者区分，用于安全重试：同一使用者以
// 相同请求号、患者、接收方、绑定授权与记录集合重试时返回原交换。
type Exchange struct {
	ID              ID
	PatientID       ID
	ReceiverID      string
	AuthorizationID ID
	RequestID       string
	CreatorID       string // 创建交换的内部使用者标识
	Status          string // ExchangePending/Accepted/Rejected
	Digest          string // 包内容摘要，接收方回执时须原样回传
	Package         Package
	Receipt         *Receipt
	CreatedAt       time.Time
}

// 失败一律返回明确错误，不留下半条记录。
var (
	// ErrNotFound 表示引用的患者、就诊、记录、版本或授权不存在。
	ErrNotFound = errors.New("clinical: referenced object not found")
	// ErrMismatchedPatient 表示混用了属于不同患者的对象。
	ErrMismatchedPatient = errors.New("clinical: objects belong to different patients")
	// ErrInvalidArgument 表示参数本身不合法（空内容、空范围、时间窗倒置等）。
	ErrInvalidArgument = errors.New("clinical: invalid argument")
	// ErrConflict 表示乐观并发冲突：指定的版本已不再是当前版本。
	ErrConflict = errors.New("clinical: version conflict")
	// ErrDeactivated 表示患者档案已停用，该写操作不再允许。
	ErrDeactivated = errors.New("clinical: patient record is deactivated")
	// ErrActive 表示记录已有生效版本，不能按草稿方式直接覆盖或删除。
	ErrActive = errors.New("clinical: record is already effective")
	// ErrAccessDenied 表示接收方没有覆盖所请求范围的有效授权，
	// 或内部规则不允许该身份执行此操作。返回时不携带任何受保护内容。
	ErrAccessDenied = errors.New("clinical: access denied")
	// ErrClosed 表示 Store 已关闭。
	ErrClosed = errors.New("clinical: store closed")
)

