139	func assertAuthIDsSorted(t *testing.T, auths []Authorization) {
140		t.Helper()
141		for i := 1; i < len(auths); i++ {
142			if auths[i-1].ID >= auths[i].ID {
143				t.Fatalf("authorizations not sorted ascending by id: %q before %q",
144					auths[i-1].ID, auths[i].ID)
145			}
146		}
147	}
