77	// 先占用存储互斥锁，待创建 goroutine 发出请求并阻塞后，把时钟推进到 advanceTo
78	// （即“等待结束、真正开始核对本次授权”的时刻），再放行。返回创建结果与错误。
79	func createExchangeWhileStoreBusy(f *createExchangeTimingFixture, advanceTo time.Time, authID ID, req string) (Exchange, error) {
80		f.s.mu.Lock()
81		type outcome struct {
82			x   Exchange
83			err error
84		}
85		done := make(chan outcome, 1)
86		go func() {
87			x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, authID, []ID{f.diag, f.ord}, req)
88			done <- outcome{x, err}
89		}()
90		// 给创建 goroutine 留出进入 CreateExchange 并阻塞在锁上的时间，确保请求
91		// 是在时钟推进之前发出的——核对只能采用 advanceTo 这一时刻。
92		time.Sleep(50 * time.Millisecond)
93		f.clk.t = advanceTo
94		f.s.mu.Unlock()
95		o := <-done
96		return o.x, o.err
97	}
