386		}
387	
388		// 开始前一纳秒：拒绝，不新增。
389		before = fingerprintStore(t, &f)
390		f.setClock(start.Add(-time.Nanosecond))
391		x4, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.bound,
392			[]ID{f.diag, f.ord}, "req-start-minus-1ns")
393		assertTimingDenied(t, x4, err)
394		assertFingerprintEqual(t, before, fingerprintStore(t, &f))
395		if countExchanges() != 2 || countCreateAudits() != 2 {
396			t.Fatal("denied create before start must add no exchange or audit")
397		}
398	}
399	
400	// 被时间条件拒绝时，已存在的交换、记录与授权保持提交前内容：先在窗口内成功
401	// 创建一份交换（待回执），再让一个全新请求号在等待中跨过截止时刻被拒；随后
402	// 比对交换（含原包摘要与内容）、审计、授权和记录完整历史逐项不变。另一条仍
403	// 有效且覆盖相同记录的授权在场，绑定授权到期仍必须拒绝、不得替代。
404	func TestCreateExchangeDenialPreservesExistingState(t *testing.T) {
405		start, end := timingBase, timingBase.Add(time.Hour)
406		f := setupCreateExchangeTiming(t, start, end)
407		grantOtherCoveringSameRecords(t, &f, start, end.Add(2*time.Hour))
408	
409		// 先成功创建一份交换，作为“已有交换”。
410		f.setClock(start.Add(30 * time.Minute))
411		existing, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.bound,
412			[]ID{f.diag, f.ord}, "req-existing-ok")
413		if err != nil {
414			t.Fatalf("seed exchange: %v", err)
415		}
416		gotExisting, err := f.s.GetExchange(doc, f.pid, existing.ID)
417		if err != nil {
418			t.Fatalf("get seed exchange: %v", err)
419		}
420	
421		before := fingerprintStore(t, &f)
422	
423		// 新请求在 09:59 发出，等待期间到达 10:00：核对时绑定授权已失效。
424		f.setClock(end.Add(-time.Minute))
425		x, err := createExchangeWhileStoreBusy(&f, end, f.bound, "req-denied-keeps-state")
426		assertTimingDenied(t, x, err)
427	
428		// 交换、审计、授权、记录完整历史逐项保持提交前内容。
429		assertFingerprintEqual(t, before, fingerprintStore(t, &f))
430	
431		// 已有的那份交换仍可逐字取回，状态/摘要/包内容不变。
432		gotAfter, err := f.s.GetExchange(doc, f.pid, existing.ID)
433		if err != nil {
434			t.Fatalf("get seed exchange after denial: %v", err)
435		}
436		if !reflect.DeepEqual(gotExisting, gotAfter) {
437			t.Fatalf("existing exchange changed:\nbefore=%+v\nafter=%+v", gotExisting, gotAfter)
438		}
439	}
440

