283	func newID(prefix string) string {
284		var b [12]byte
285		if _, err := rand.Read(b[:]); err != nil {
286			// crypto/rand 失败在正常运行环境中不应发生；无法安全生成标识时直接中断。
287			panic(fmt.Errorf("clinical: cannot generate id: %w", err))
288		}
289		return prefix + "_" + hex.EncodeToString(b[:])
290	}
