292	func (s *Store) addAudit(snap *snapshot, patientID ID, actor Actor, action, objectType, objectID ID, at time.Time) {
293		snap.AuditEvents = append(snap.AuditEvents, &AuditEvent{
294			ID:         newID("aud"),
295			PatientID:  patientID,
296			ActorID:    actor.ID,
297			Action:     action,
298			ObjectType: objectType,
299			ObjectID:   objectID,
300			OccurredAt: at,
301		})
302	}
